// FIX29 (WP6a): the shared golden fixtures.
//
// `fixtures/policy-goldens.json` holds worked examples of the remote policy.
// Its `expect` values were generated by the TypeScript functions and are the
// contract: every case must keep passing on this side, and the Rust port in
// `crates/bloblex-daemon/src/remote/policy.rs` runs the same file (via
// `include_str!`) through its own implementation, so the two ports cannot
// drift. Do not hand-edit an `expect` value to make a test pass; regenerate it
// from the implementation and review the change.

import { describe, expect, it } from 'vitest'
import {
  authorizeRemoteCall,
  redactEventForRemote,
  redactResultForRemote,
  redactSnapshotForRemote,
  type RedactOptions,
  type RemoteCall,
  type RemoteCallDecision,
} from './remoteTiers'
import goldensJson from './fixtures/policy-goldens.json'

interface AuthorizeCase {
  name: string
  call: RemoteCall
  expect: RemoteCallDecision
}

interface ResultCase {
  name: string
  method: string
  options: RedactOptions
  input: unknown
  expect: unknown
}

interface SnapshotCase {
  name: string
  options: RedactOptions
  input: unknown
  expect: unknown
}

interface EventCase {
  name: string
  input: unknown
  expect: unknown
}

interface Goldens {
  authorize: readonly AuthorizeCase[]
  results: readonly ResultCase[]
  snapshots: readonly SnapshotCase[]
  events: readonly EventCase[]
}

const goldens = goldensJson as Goldens

describe('shared policy goldens (TypeScript)', () => {
  it('carries the case counts the Rust port also runs', () => {
    expect(goldens.authorize.length).toBeGreaterThanOrEqual(15)
    expect(goldens.results.length).toBeGreaterThanOrEqual(10)
    expect(goldens.snapshots.length).toBeGreaterThanOrEqual(4)
    expect(goldens.events.length).toBeGreaterThanOrEqual(10)
  })

  it('names every case', () => {
    for (const group of [goldens.authorize, goldens.results, goldens.snapshots, goldens.events]) {
      for (const testCase of group) expect(testCase.name.length, JSON.stringify(testCase)).toBeGreaterThan(0)
    }
  })
})

describe('goldens: authorizeRemoteCall', () => {
  for (const testCase of goldens.authorize) {
    it(testCase.name, () => {
      expect(authorizeRemoteCall(testCase.call)).toEqual(testCase.expect)
    })
  }
})

describe('goldens: redactResultForRemote', () => {
  for (const testCase of goldens.results) {
    it(testCase.name, () => {
      expect(redactResultForRemote(testCase.method, testCase.input, testCase.options)).toEqual(testCase.expect)
    })
  }
})

describe('goldens: redactSnapshotForRemote', () => {
  for (const testCase of goldens.snapshots) {
    it(testCase.name, () => {
      expect(redactSnapshotForRemote(testCase.input, testCase.options)).toEqual(testCase.expect)
    })
  }
})

describe('goldens: redactEventForRemote', () => {
  for (const testCase of goldens.events) {
    it(testCase.name, () => {
      if (testCase.expect === null) expect(redactEventForRemote(testCase.input)).toBeNull()
      else expect(redactEventForRemote(testCase.input)).toEqual(testCase.expect)
    })
  }
})
